DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.recycling_action(text,jsonb)'::regprocedure) INTO d;
d:=replace(d,'IF action=''assign'' THEN','IF action=''cancel'' THEN IF r.buyer_id<>uid OR r.status NOT IN (''submitted'',''assigned'',''accepted'',''scheduled'') THEN RAISE EXCEPTION ''Cancellation not allowed''; END IF; UPDATE public.recycling_requests SET status=''cancelled'' WHERE id=rid; ELSIF action=''assign'' THEN');
EXECUTE d;
END $$;
ALTER TABLE public.recycling_requests DROP CONSTRAINT IF EXISTS recycling_requests_status_check;
ALTER TABLE public.recycling_requests ADD CONSTRAINT recycling_requests_status_check CHECK(status IN ('submitted','assigned','accepted','scheduled','collected','verified','rejected','cancelled'));
CREATE OR REPLACE FUNCTION public.resubmit_supplier() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.account_active(auth.uid()) THEN RAISE EXCEPTION 'Active supplier required'; END IF; PERFORM set_config('greenswitch.resubmitting',auth.uid()::text,true); UPDATE public.supplier_profiles SET verification_status='pending',rejection_reason='' WHERE user_id=auth.uid() AND verification_status='rejected'; IF NOT FOUND THEN RAISE EXCEPTION 'Rejected application required'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.guard_supplier_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND (NEW.verification_status IS DISTINCT FROM OLD.verification_status OR NEW.is_demo IS DISTINCT FROM OLD.is_demo OR NEW.user_id IS DISTINCT FROM OLD.user_id) AND NOT (current_user NOT IN ('anon','authenticated') AND current_setting('greenswitch.resubmitting',true)=auth.uid()::text AND OLD.user_id=auth.uid() AND OLD.verification_status='rejected' AND NEW.verification_status='pending' AND NEW.is_demo=OLD.is_demo AND NEW.user_id=OLD.user_id) THEN RAISE EXCEPTION 'Only administrators may change verification or ownership'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.approval_status(uid uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.account_access WHERE user_id=uid AND status IN ('pending','rejected','suspended')) THEN (SELECT status FROM public.account_access WHERE user_id=uid) WHEN EXISTS(SELECT 1 FROM public.supplier_profiles WHERE user_id=uid AND verification_status<>'approved') THEN (SELECT verification_status FROM public.supplier_profiles WHERE user_id=uid) WHEN EXISTS(SELECT 1 FROM public.recycling_partners WHERE user_id=uid AND NOT approved) THEN 'pending' ELSE 'approved' END $$;
REVOKE ALL ON FUNCTION public.approval_status(uuid) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.admin_manage(text,jsonb)'::regprocedure) INTO d;
d:=replace(d,'ELSIF action=''partner_areas'' THEN','IF status_value=''active'' AND EXISTS(SELECT 1 FROM public.supplier_profiles WHERE user_id=target AND verification_status<>''approved'') THEN SELECT id INTO sid FROM public.supplier_profiles WHERE user_id=target; PERFORM public.admin_verify_supplier(sid,''approved''); ELSIF status_value=''rejected'' THEN UPDATE public.supplier_profiles SET verification_status=''rejected'',rejection_reason=coalesce(payload->>''reason'','''') WHERE user_id=target; END IF; IF status_value IN (''active'',''rejected'') THEN UPDATE public.recycling_partners SET approved=(status_value=''active'') WHERE user_id=target; END IF; ELSIF action=''partner_areas'' THEN'); EXECUTE d;
END $$;
CREATE FUNCTION public.resubmit_account() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; UPDATE public.account_access SET status='pending',reason='' WHERE user_id=auth.uid() AND status='rejected'; IF NOT FOUND THEN RAISE EXCEPTION 'Rejected application required'; END IF; END $$;
REVOKE ALL ON FUNCTION public.resubmit_account() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resubmit_account() TO authenticated;
CREATE POLICY group_owner_business_read ON public.business_profiles FOR SELECT TO authenticated USING(public.account_active(auth.uid()) AND EXISTS(SELECT 1 FROM public.group_buying_participants g JOIN public.group_buying_campaigns c ON c.id=g.campaign_id WHERE g.user_id=business_profiles.user_id AND public.owns_supplier(c.supplier_id)));